  "employEWalk": "<a href=\"/\" class=\"text-amber-300 underline\">Home</a> · <a href=\"/chat.html\" class=\"text-amber-300 underline\">Chat</a> · <a href=\"/employ.html\" class=\"text-amber-300 underline\">Employ</a> · <a href=\"/pilot.html\" class=\"text-amber-300 underline\">Pilot</a> · <a href=\"/Launch-Ra-Thor.html\" class=\"text-amber-300 underline\">Launch</a> · <a href=\"/micro-moment.html\" class=\"text-amber-300 underline\">Moments</a> · <a href=\"/sovereign-shard.html\" class=\"text-amber-300 underline\">Shard</a> · <a href=\"/web-forge.html\" class=\"text-amber-300 underline\">Forge</a> · <a href=\"/contact.html\" class=\"text-amber-300 underline\">Contact</a> · <a href=\"/privacy.html\" class=\"text-amber-300 underline\">Privacy</a>",
  "employFBody": "AG-SML v1.2: personal, educational, research, and non-commercial creative use — free when non-revenue. Revenue or LICENSE §2 organization use → paid licence. Use the <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">commercial inquiry form</a> or write <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>.",
  "employFTitle": "F. License",
  "employGBody": "No measured METR numbers. No cert filing. The work pack is a <strong class=\"text-amber-300\">DRAFT</strong>.",
  "employGTitle": "G. Honest gaps",
  "employLoop1": "<strong class=\"text-amber-300\">Intend</strong> — ask for a draft, a plan, a review, or a refusal.",
  "employLoop2": "<strong class=\"text-amber-300\">Pass the TOLC 8 mercy checks</strong> — TOLC 8 is the standing test.",
  "employLoop3": "<strong class=\"text-amber-300\">Optional model</strong> — stay on-device, or copy context into a model you choose.",
  "employLoop4": "<strong class=\"text-amber-300\">Review</strong> — read the draft. Keep or refuse.",
  "employLoop5": "<strong class=\"text-amber-300\">Act</strong> — you own the action.",
  "employLoopFoot": "Optional-model contract: <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/OPTIONAL_MODEL.md\" class=\"text-amber-300 underline\">docs/OPTIONAL_MODEL.md</a>. Not a certified AgentOS or Hermes integration.",
  "employLoopTitle": "The loop",
  "employOrgBuy": "What you're paying for: time, and the right to connect one workflow under the same rules. You can look at everything first, then keep it or walk away.",
  "employOrgHow": "How to inquire: the <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">commercial inquiry</a> form, the <a href=\"/pilot.html\" class=\"text-amber-300 underline\">2–6 week pilot</a>, or <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>. A human replies. There is no instant license key.",
  "employOrgNot": "What they do not buy: ISO 42001, EU AI Act conformity, METR numbers, an AGSi warranty, a hosted key proxy, or a finished world.",
  "employOrgTitle": "Organizations",
  "employOrgWho": "Who pays: organization use, selling the Software or a fork, wrapper, or hosted instance, hosting the Software for profit, a product embed, client service at organizational scale, or a staff-agent constitution.",
  "employBotCoord": "Coordination runs through GitHub — PRs, one council-board issue, and direct bot-to-bot messages when a seat needs a handoff.",
  "employBotHonesty": "Honesty line: no fake approvals or scores. Gaps are flagged, never filled in.",
  "employBotLead": "Inspectable research software with Mercy-Checks: a small team of bots you run on your repo, not a hosted agent farm. Organizations can ask about this through <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>.",
  "employBotMerge1": "One draft PR from the tip of main.",
  "employBotMerge2": "Green CI on the exact PR head.",
  "employBotMerge3": "Each seat posts its vote on that exact head SHA.",
  "employBotMerge4": "Any new push voids the votes — seats vote again.",
  "employBotMerge5": "Squash merge pinned to that SHA.",
  "employBotMerge6": "A live check that the change is really on the site.",
  "employBotMergeIntro": "Nothing lands without the Mercy-Ways process:",
  "employBotMergeTitle": "Mercy-Checks merge",
  "employBotOwner": "Owner-only (human, always): payments, publishing, pricing, outreach, new public claims, and locked files.",
  "employBotPlaybook": "Full playbook: <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/EMPLOY_BOT_TEAM.md\" class=\"text-amber-300 underline\">docs/EMPLOY_BOT_TEAM.md</a>.",
  "employBotRoute": "A lead bot receives each card, keeps scope honest, and routes work to the right council seat.",
  "employBotSeatCore": "<strong class=\"text-amber-300\">Core</strong> — votes on runtime, workflows, service worker, manifest, keys, security, public API, and public AI-read text.",
  "employBotSeatPaths": "<strong class=\"text-amber-300\">Paths</strong> — votes on which files and paths the change touches, proving it stays in scope.",
  "employBotSeatReviewer": "<strong class=\"text-amber-300\">Reviewer</strong> — votes on the change itself: scope, honesty, and wording.",
  "employBotSeatsTitle": "Three council seats",
  "employBotSetup1": "Create a lead bot for your organization.",
  "employBotSetup2": "Add the three seat bots (Reviewer, Paths, Core).",
  "employBotSetup3": "Connect GitHub with the permissions your merge process needs.",
  "employBotSetup4": "Name one council-board issue for stall flags and HOLD notes.",
  "employBotSetup5": "Turn on an hourly stall watchdog (flags only — it never merges, reverts, or pushes).",
  "employBotSetupTitle": "Five-step setup",
  "employBotTitle": "Run your organization's own governed bot team",
  "employSisterBody": "Curriculum, the human game, and inspectable studies live in their own GitHub repos — not as extra product doors on this site. Open the map: <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/SISTER_ADOPTION.md\" class=\"text-amber-300 underline\">docs/SISTER_ADOPTION.md</a>. Fusion, High-Tc, protein, and worldship work stay studies you inspect there.",
